INSERT INTO public.ejercicios (id, leccion_id, palabra_id, tipo, instruccion, opciones, respuesta_correcta, puntos, orden, activo, creado_en) VALUES ('22222222-2222-4222-8222-222222222201', '11111111-1111-4111-8111-111111111101', 'd1b8a82f-2151-4251-8af0-b1e25f067700', 'opcion_multiple', '¿Qué significa el saludo cotidiano «¿Gen tonok?» en español?', '["¿Cómo estás?","¿Dónde vas?","Hasta mañana","No escucho"]', '¿Cómo estás?', 15, 1, true, '2026-10-29 18:14:13.574747+00'), ('22222222-2222-4222-8222-222222222202', '11111111-1111-4111-8111-111111111101', '71f42eb5-8f56-4d92-98bd-9a70f18fa174', 'opcion_multiple', 'Cuando alguien llega de visita y le dices «Ximotali», ¿qué le estás indicando?', '["Siéntate","Duerme","Escribe","Camina"]', 'Siéntate', 15, 2, true, '2026-10-29 18:14:13.574747+00'), ('22222222-2222-4222-8222-222222222203', '11111111-1111-4111-8111-111111111101', 'c116b213-a109-48ac-a95e-f39e6f1fe55e', 'opcion_multiple', '¿Cómo se agradece diciendo «Gracias» en el náhuatl de la región sur de Veracruz?', '["Tasohkamati","Mosta timottah","Niyegonok","Xitagagi"]', 'Tasohkamati', 15, 3, true, '2026-10-29 18:14:13.574747+00'), ('22222222-2222-4222-8222-222222222204', '11111111-1111-4111-8111-111111111101', 'e7aaf5c4-aa92-4048-97ce-031841f918c0', 'comprension_auditiva', 'Escucha el audio de la clase («¡Ayamó xikpohpo!») y selecciona qué le pides al profesor (tamaxtiani):', '["¡Todavía no lo borres!","¡No lo escucho, profesor!","¿Cómo se escribe venado?","No lo puedo escribir"]', '¡Todavía no lo borres!', 20, 4, true, '2026-10-29 18:14:13.574747+00'), ('22222222-2222-4222-8222-222222222205', '11111111-1111-4111-8111-111111111101', 'a598260e-3944-4483-8c56-7dd5ea1ebed1', 'emparejar_pares', 'Empareja cada expresión en náhuatl con su significado correcto en español:', '{"pares":[{"nahuat":"¿Gen tonok?","espanol":"¿Cómo estás?"},{"nahuat":"Niyegonok","espanol":"Estoy bien"},{"nahuat":"Mosta timottah","espanol":"Mañana nos vemos"},{"nahuat":"Tasohkamati","espanol":"Gracias"}]}', 'completado', 25, 5, true, '2026-10-29 18:14:13.574747+00');